// Synchronous ROM: q = 6-bit character code of character 'idx' of COCO class
// 'class_id' (project label, max 14 chars). Codes: 0=' ' 1..26=A..Z 27..36=0..9
// 37='%' 38='-'.  name_len() gives the visible length of each class name.
// -----------------------------------------------------------------------------
module coco_label_rom (
    input  wire       clk,
    input  wire [6:0] class_id,
    input  wire [3:0] idx,
    output reg  [5:0] q
