// Length of each displayed label; 0 = not a project class (overlay ignores it).
module coco_name_len (
    input  wire [7:0] class_id,
    output reg  [3:0] len
);
    always @* begin
        case (class_id)
            8'd0: len = 4'd6;  // person -> PERSON
            8'd24: len = 4'd3;  // backpack -> BAG
            8'd26: len = 4'd5;  // handbag -> POUCH
            8'd39: len = 4'd6;  // bottle -> BOTTLE
            8'd41: len = 4'd3;  // cup -> CUP
            8'd63: len = 4'd6;  // laptop -> LAPTOP
            8'd64: len = 4'd5;  // mouse -> MOUSE
            8'd66: len = 4'd8;  // keyboard -> KEYBOARD
            8'd67: len = 4'd6;  // cell phone -> MOBILE
            8'd73: len = 4'd8;  // book -> NOTEBOOK
            default: len = 4'd0;
        endcase
    end
endmodule
